-- M17 section 3.3 / D3: config_change_log only grows. A record of who changed the dispute appeal window
-- from 7 days to 1 is worth nothing if the same person can edit it afterwards. Generated by appendOnly()
-- in src/db/helpers/appendOnly.ts: UPDATE and DELETE raise KT001 for everyone including the owner, and
-- komtru_app holds INSERT and SELECT only.
CREATE TRIGGER komtru_append_only BEFORE UPDATE OR DELETE ON "config"."config_change_log" FOR EACH ROW EXECUTE FUNCTION platform.reject_mutation();
--> statement-breakpoint
REVOKE ALL ON "config"."config_change_log" FROM komtru_app;
--> statement-breakpoint
GRANT INSERT, SELECT ON "config"."config_change_log" TO komtru_app;
